+function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);rain=Array.from({length:Math.floor(W*H/6000)},()=>({x:Math.random()*W,y:Math.random()*H,l:8+Math.random()*18,s:3+Math.random()*6,a:.1+Math.random()*.22}));player.x=W*.325;enemy.x=W*.675;}
+window.addEventListener('resize',resize);resize();
