+function lineName(l){return l==='high'?'HIGH':l==='mid'?'MID':'LOW'}
+function startGame(){player.health=100;enemy.health=100;player.stamina=100;enemy.stamina=100;player.mode='idle';enemy.mode='idle';player.timer=0;enemy.timer=0;player.parry=0;enemy.parry=0;enemy.think=1.6;player.attackCount=0;enemy.attackCount=0;particles=[];gameOn=true;paused=false;guarding=false;ui.start.classList.add('hidden');ui.hud.classList.add('active');ui.result.classList.remove('show');setStatus('');updateHud();}
