+function doParry(){if(!gameOn||paused||player.mode==='stunned'||player.stamina<9)return;player.parry=.48;player.stamina-=9;player.mode='parry';player.timer=.25;setStatus('');updateHud();}
+function beginGuard(e){e?.preventDefault();if(!gameOn||paused)return;guarding=true;player.guard=true;document.querySelector('#blockBtn').classList.add('held');if(player.mode==='idle')player.mode='guard';}
+function endGuard(){guarding=false;player.guard=false;document.querySelector('#blockBtn').classList.remove('held');if(player.mode==='guard')player.mode='idle';}
+function feint(){if(!gameOn||paused||player.mode!=='windup')return;player.mode='idle';player.timer=0;player.stamina=Math.min(100,player.stamina+9);setStatus('FEINT');setTimeout(()=>{if(ui.status.textContent==='FEINT')setStatus('')},500);updateHud();}
+document.querySelector('#attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();doAttack()});document.querySelector('#parryBtn').addEventListener('pointerdown',e=>{e.preventDefault();doParry()});document.querySelector('#feintBtn').addEventListener('pointerdown',e=>{e.preventDefault();feint()});
