+function startEnemyAttack(){if(!gameOn||enemy.stamina<16)return;enemy.mode='telegraph';enemy.timer=.92;enemy.line=dirs[Math.floor(Math.random()*3)];enemy.stamina-=16;enemy.attackCount++;setStatus(`${lineName(enemy.line)} INCOMING`);updateHud();}
+function enemyStrike(){if(!gameOn)return;enemy.mode='recover';enemy.timer=.62;enemy.stamina=Math.max(0,enemy.stamina);if(player.parry>0){player.parry=0;enemy.mode='stunned';enemy.timer=.9;enemy.stamina=Math.max(0,enemy.stamina-24);shake=7;emit((player.x+enemy.x)/2,H*.68,'#9ccfc1',20,1.2);setStatus('PARRY · RIPOSTE');player.stamina=Math.min(100,player.stamina+11);updateHud();return}if(player.guard){const same=player.guardLine===enemy.line;if(same||player.guardLine==='mid'){impact(player,0,true);player.stamina=Math.max(0,player.stamina-10)}else impact(player,16,false)}else impact(player,21,false);}
+function playerStrike(){if(!gameOn)return;player.mode='recover';player.timer=.54;let guarded=enemy.mode==='guard'&&enemy.guardLine===player.line;if(enemy.mode==='telegraph'&&enemy.timer<.18){guarded=false}if(enemy.mode==='telegraph'&&Math.random()<.12)guarded=true;if(guarded){impact(enemy,0,true);enemy.stamina=Math.max(0,enemy.stamina-8)}else{impact(enemy,19,false);enemy.think=Math.max(enemy.think,1.35)}}
+function tick(dt){if(!gameOn||paused)return;elapsed+=dt;player.stamina=Math.min(100,player.stamina+dt*(player.guard?5:13));enemy.stamina=Math.min(100,enemy.stamina+dt*10);if(player.parry>0)player.parry-=dt;if(player.mode==='windup'){player.timer-=dt;if(player.timer<=0){player.mode='swing';player.timer=.25;playerStrike()}}else if(player.mode==='swing'){player.timer-=dt;if(player.timer<=0&&player.mode==='swing'){player.mode='recover';player.timer=.4}}else if(['recover','stunned','parry'].includes(player.mode)){player.timer-=dt;if(player.timer<=0)player.mode=player.guard?'guard':'idle'}
+if(player.guard)player.guardLine=selected;
+if(enemy.mode==='telegraph'){enemy.timer-=dt;if(enemy.timer<=0){enemy.mode='swing';enemy.timer=.28;enemyStrike()}}else if(enemy.mode==='swing'){enemy.timer-=dt;if(enemy.timer<=0&&enemy.mode==='swing'){enemy.mode='recover';enemy.timer=.55}}else if(enemy.mode==='recover'||enemy.mode==='stunned'||enemy.mode==='guard'){enemy.timer-=dt;if(enemy.timer<=0)enemy.mode='idle'}
+if(enemy.mode==='idle'){enemy.think-=dt;if(enemy.think<=0){if(player.mode==='windup'&&Math.random()<.28){enemy.mode='guard';enemy.guardLine=player.line;enemy.timer=.7}else startEnemyAttack();enemy.think=rand(1.3,2.1)}}
+if(player.mode==='guard'&&!player.guard)player.mode='idle';if(player.mode==='idle'&&!player.guard)player.stamina=Math.min(100,player.stamina+dt*5);if(enemy.mode==='idle')enemy.stamina=Math.min(100,enemy.stamina+dt*4);particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=140*dt;p.vx*=.98});particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-dt*22);flash=Math.max(0,flash-dt);updateHud();}

