function path(points,close=true){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);if(close)ctx.closePath()}
function gradient(x,y,x2,y2,stops){const g=ctx.createLinearGradient(x,y,x2,y2);stops.forEach(s=>g.addColorStop(s[0],s[1]));return g}
function drawLamp(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#111817';ctx.fillRect(-3,-155,6,155);ctx.fillRect(-17,-153,34,4);ctx.fillRect(-12,-147,24,3);ctx.beginPath();ctx.moveTo(-7,-148);ctx.lineTo(-5,-130);ctx.lineTo(-11,-115);ctx.lineTo(11,-115);ctx.lineTo(5,-130);ctx.lineTo(7,-148);ctx.closePath();ctx.fill();ctx.fillStyle='#d5a25e';ctx.shadowColor='#efa948';ctx.shadowBlur=27;ctx.beginPath();ctx.ellipse(0,-130,3.8,8,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#718277';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-15,-155);ctx.lineTo(0,-161);ctx.lineTo(15,-155);ctx.stroke();ctx.restore()}
function drawBuilding(x,y,w,h,tone,detail=0){ctx.fillStyle=tone;ctx.fillRect(x,y,w,h);ctx.fillStyle='#080d0e66';ctx.fillRect(x,y,w,8);for(let r=0;r<Math.ceil(h/47);r++){for(let c=0;c<Math.floor(w/35);c++){let wx=x+10+c*35+(r%2)*17,wy=y+18+r*47;if(wx+14>x+w-5)continue;ctx.fillStyle=detail&&((c*7+r*3+detail)%9===0)?'#a8744c':'#111a1b';ctx.fillRect(wx,wy,14,24);ctx.fillStyle='#dbc080';ctx.globalAlpha=.35+Math.sin(elapsed*1.3+c+r)*.09;if(detail&&((c*7+r*3+detail)%9===0))ctx.fillRect(wx+3,wy+3,8,18);ctx.globalAlpha=1;ctx.fillStyle='#6b5940';ctx.fillRect(wx-1,wy+23,16,2)}}ctx.fillStyle='#101718';ctx.fillRect(x+w*.12,y-10,w*.76,12);ctx.fillStyle='#202927';for(let i=0;i<5;i++){ctx.fillRect(x+w*.1+i*w*.18,y+h-14,4,14)}}
function drawBackground(){let sky=gradient(0,0,0,H,[[0,'#172326'],[.43,'#34413d'],[.68,'#232c2a'],[1,'#111819']]);ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);const glow=ctx.createRadialGradient(W*.5,H*.47,5,W*.5,H*.47,W*.58);glow.addColorStop(0,'#b3895c20');glow.addColorStop(1,'#141a1a00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.8);
// layered Victorian roofline
const base=H*.59;drawBuilding(-20,H*.18,W*.22,H*.44,'#1a2424',2);drawBuilding(W*.16,H*.11,W*.19,H*.52,'#202a29',5);drawBuilding(W*.68,H*.15,W*.2,H*.49,'#1e2928',4);drawBuilding(W*.84,H*.22,W*.2,H*.42,'#172121',1);
ctx.fillStyle='#101717';ctx.beginPath();ctx.moveTo(0,H*.2);ctx.lineTo(W*.1,H*.11);ctx.lineTo(W*.13,H*.2);ctx.lineTo(W*.21,H*.17);ctx.lineTo(W*.21,base);ctx.lineTo(0,base);ctx.fill();ctx.beginPath();ctx.moveTo(W*.78,H*.19);ctx.lineTo(W*.86,H*.1);ctx.lineTo(W*.9,H*.2);ctx.lineTo(W,H*.16);ctx.lineTo(W,base);ctx.lineTo(W*.78,base);ctx.fill();
// distant fog and chimneys
for(let i=0;i<8;i++){let x=W*(.06+i*.125),y=H*(.12+(i%3)*.035);ctx.fillStyle='#111a1a';ctx.fillRect(x,y-35,7,50);ctx.fillRect(x-3,y-37,13,4);for(let k=0;k<3;k++){let sy=((elapsed*13+k*43+i*31)%(H*.22))+y-H*.24;ctx.fillStyle=`rgba(166,173,154,${.025+k*.009})`;ctx.beginPath();ctx.ellipse(x+Math.sin(elapsed*.27+i+k)*13,sy,13+k*4,7+k*2,0,0,Math.PI*2);ctx.fill()}}
// distant street
ctx.fillStyle='#39413a';ctx.fillRect(0,base,W,H*.11);ctx.fillStyle=gradient(0,base,0,H,[[0,'#343a34'],[.22,'#202825'],[1,'#111718']]);path([[0,base],[W,base],[W,H],[0,H]]);ctx.fill();
// paving converges to vanishing point
for(let i=0;i<15;i++){let y=base+(H-base)*Math.pow(i/14,1.8);ctx.strokeStyle=`rgba(146,145,120,${.05+i*.004})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(let i=0;i<17;i++){let x=W*i/16,top=W*.5+(x-W*.5)*.11;ctx.strokeStyle='#a5a18a18';ctx.beginPath();ctx.moveTo(top,base);ctx.lineTo(x,H);ctx.stroke()}
// trolley tracks and warm reflections
ctx.strokeStyle='#9a876149';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(W*.44,base);ctx.lineTo(W*.36,H);ctx.moveTo(W*.56,base);ctx.lineTo(W*.64,H);ctx.stroke();ctx.strokeStyle='#cba56a22';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(W*.21,H*.83);ctx.lineTo(W*.35,H*.88);ctx.moveTo(W*.72,H*.91);ctx.lineTo(W*.88,H*.84);ctx.stroke();
// gaslight pools
const pool=ctx.createRadialGradient(W*.2,H*.56,3,W*.2,H*.56,W*.28);pool.addColorStop(0,'#d7a45c22');pool.addColorStop(1,'#d7a45c00');ctx.fillStyle=pool;ctx.fillRect(0,H*.27,W*.55,H*.65);const pool2=ctx.createRadialGradient(W*.81,H*.57,2,W*.81,H*.57,W*.2);pool2.addColorStop(0,'#d2965620');pool2.addColorStop(1,'#d2965600');ctx.fillStyle=pool2;ctx.fillRect(W*.55,H*.25,W*.45,H*.65);
drawLamp(W*.19,H*.63,Math.max(.7,H/700));drawLamp(W*.81,H*.62,Math.max(.58,H/820));
// street fixtures, crates, wheel
ctx.fillStyle='#141b1a';ctx.fillRect(W*.035,H*.59,W*.095,H*.07);ctx.strokeStyle='#726849';ctx.lineWidth=2;ctx.strokeRect(W*.035,H*.59,W*.095,H*.07);ctx.beginPath();ctx.arc(W*.11,H*.68,H*.027,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#262e2a';ctx.fillRect(W*.82,H*.6,W*.1,H*.065);ctx.strokeStyle='#78694e';ctx.strokeRect(W*.82,H*.6,W*.1,H*.065);
// low moving mist
for(let i=0;i<5;i++){let x=((i*W*.27+elapsed*9)%(W*1.4))-W*.2,y=H*(.62+(i%3)*.045);ctx.fillStyle=`rgba(177,185,165,${.025+(i%2)*.012})`;ctx.beginPath();ctx.ellipse(x,y,70+i*15,9+i*2,0,0,Math.PI*2);ctx.fill()}
}
function drawRain(dt){ctx.save();ctx.strokeStyle='#b8c5c0';ctx.lineWidth=1;for(const r of rain){r.y+=r.s*(dt*60);r.x-=r.s*.26*dt*60;if(r.y>H+20){r.y=-20;r.x=Math.random()*W}ctx.globalAlpha=r.a;ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-3,r.y+r.l);ctx.stroke()}ctx.globalAlpha=1;ctx.restore()}

